it.effect("uses the bound native cwd only when launch options omit it", () =>
  Effect.gen(function* () {
    for (const explicit of [undefined, "/explicit-native-workspace"]) {
      const fake = mockSpawn();
      fake.startup.resolve(fake.ready);
      const host = yield* createMuseSdkHostEffect({
        binaryPath: "/custom/muse", launch: { command: "/custom/muse", args: [] },
        environment: { MUSE_HOME: "./relative-native-home" },
        ...(explicit === undefined ? {} : { cwd: explicit }),
      });
      expect(vi.mocked(spawnMspConnection).mock.lastCall?.[0]).toMatchObject({
        cwd: explicit ?? "/bound-native-workspace",
      });
      fake.shutdown.resolve({ code: 0, signal: null });
      yield* Effect.promise(() => host.close());
    }
  }).pipe(Effect.provideService(HostProcess.WorkingDirectory, "/bound-native-workspace")),
);
